def search(lst):
    """
    Return the greatest positive integer whose frequency in lst is at least
    its own value. If no such integer exists, return -1.
    """
    frequencies = {}

    for num in lst:
        if num > 0:
            frequencies[num] = frequencies.get(num, 0) + 1

    result = -1
    for num, count in frequencies.items():
        if count >= num and num > result:
            result = num

    return result
```

