def match_parens(lst):
    """
    Return 'Yes' if the two parenthesis strings can be concatenated
    in some order to form a balanced string, otherwise 'No'.
    """
    def is_good_concat(first, second):
        balance = 0

        for ch in first:
            if ch == '(':
                balance += 1
            else:
                balance -= 1

            if balance < 0:
                return False

        for ch in second:
            if ch == '(':
                balance += 1
            else:
                balance -= 1

            if balance < 0:
                return False

        return balance == 0

    a, b = lst
    return 'Yes' if is_good_concat(a, b) or is_good_concat(b, a) else 'No'
```

