def split_words(txt: str):
    """
    Given a string of words:
    - If it contains whitespace, return the words split on whitespace.
    - Otherwise, if it contains commas, return the parts split on commas.
    - Otherwise, return the number of lower-case letters whose alphabet index is odd.
      Here ord('a') = 0, ord('b') = 1, ..., ord('z') = 25.
    """
    if any(ch.isspace() for ch in txt):
        return txt.split()

    if "," in txt:
        return txt.split(",")

    count = 0
    for ch in txt:
        if "a" <= ch <= "z":
            if (ord(ch) - ord("a")) % 2 == 1:
                count += 1

    return count


if __name__ == "__main__":
    print(split_words("Hello world!"))  # ["Hello", "world!"]
    print(split_words("Hello,world!"))  # ["Hello", "world!"]
    print(split_words("abcdef"))        # 3
```

