def fix_spaces(text):
    """
    Replace spaces with underscores, except that any run of more than
    two consecutive spaces is replaced with a single hyphen.
    """
    result = []
    space_count = 0

    for char in text:
        if char == " ":
            space_count += 1
        else:
            if space_count:
                if space_count > 2:
                    result.append("-")
                else:
                    result.append("_" * space_count)
                space_count = 0
            result.append(char)

    if space_count:
        if space_count > 2:
            result.append("-")
        else:
            result.append("_" * space_count)

    return "".join(result)


if __name__ == "__main__":
    assert fix_spaces("Example") == "Example"
    assert fix_spaces("Example 1") == "Example_1"
    assert fix_spaces(" Example 2") == "_Example_2"
    assert fix_spaces(" Example   3") == "_Example-3"
```

