def words_in_sentence(sentence: str) -> str:
    """
    Return a string containing only the words from `sentence`
    whose lengths are prime numbers, preserving the original order.
    """

    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False

        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2

        return True

    return " ".join(word for word in sentence.split() if is_prime(len(word)))
```

