def cycpattern_check(a, b):
    """
    Return True if the second word or any of its rotations is a substring
    of the first word.
    """
    if not b:
        return True

    if len(b) > len(a):
        return False

    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True

    return False
